// Keep HonestUI's generated-reply styles inside the reply. Its published CSS
// includes utilities that would otherwise override the desktop's own classes.
import fs from "node:fs";
import postcss from "postcss";
// HonestUI dropdowns and date pickers use Base UI portals outside the reply.
// The desktop's own menus do not use Base UI, so this keeps their styles isolated.
const scope = ":where(.generated-chat-ui, [data-base-ui-portal])";
const seen = new Set();
let output =
  "/* Generated by scripts/build-chat-styles.mjs from HonestUI. */\n";
for (const file of ["theme.css", "density.css", "ai.css", "charts.css"]) {
  const root = postcss.parse(
    fs.readFileSync(`node_modules/honestui/dist/${file}`, "utf8"),
  );
  // Published component utilities are already compiled; do not register global variants.
  root.walkAtRules("custom-variant", (rule) => rule.remove());
  root.walkRules((rule) => {
    if (rule.parent?.type === "atrule" && /keyframes$/.test(rule.parent.name))
      return;
    rule.selectors = rule.selectors.map((selector) => {
      if (selector.includes(":root") || selector.includes(":host"))
        return scope;
      if (file === "theme.css" || file === "density.css") {
        const local = `:where(.generated-chat-ui):is(${selector})`;
        if (selector === '[data-theme="dark"]')
          return `${local}, html:not(.theme-light) [data-base-ui-portal]`;
        if (selector === '[data-theme="light"]')
          return `${local}, html.theme-light [data-base-ui-portal]`;
        if (selector === '[data-style="modern"]')
          return `${local}, [data-base-ui-portal]`;
        if (selector === '[data-density="default"]')
          return `${local}, [data-base-ui-portal]`;
        return local;
      }
      return `${scope} ${selector}`;
    });
    let ancestry = "";
    for (
      let parent = rule.parent;
      parent?.type === "atrule";
      parent = parent.parent
    )
      ancestry += `${parent.name} ${parent.params};`;
    const key = ancestry + rule.toString();
    if (seen.has(key)) rule.remove();
    else seen.add(key);
  });
  output += root.toString() + "\n";
}
fs.writeFileSync("src/styles/honest-generated.css", output);
